InstructionSelector *
llvm::createZ80InstructionSelector(const Z80TargetMachine &TM,
                                   Z80Subtarget &Subtarget,
                                   Z80RegisterBankInfo &RBI) {
  return new Z80InstructionSelector(TM, Subtarget, RBI);
}
